{
  "fund_name": {
    "value": "Brackenholt Senior Lending Fund, LP",
    "citation": "Section 1.1",
    "quote": "**Fund:** Brackenholt Senior Lending Fund, LP, a Delaware limited partnership (the \"Fund\")."
  },
  "fund_domicile": {
    "value": "Delaware (U.S.) — organized under the Delaware Revised Uniform Limited Partnership Act on January 22, 2024",
    "citation": "Section 2.1",
    "quote": "Brackenholt Senior Lending Fund, LP was formed as a limited partnership under the Delaware Revised Uniform Limited Partnership Act on January 22, 2024 and commenced operations on October 1, 2024 (the \"Initial Closing Date\")."
  },
  "fund_structure": {
    "value": "Open-end, evergreen (not a closed-end drawdown vehicle): no fixed term, no capital drawdowns, monthly subscriptions at NAV. However, Interests are NOT redeemable on demand — liquidity is provided only through discretionary quarterly repurchase offers. NOT master-feeder: the Fund is not a feeder fund, does not invest through a master fund and has no feeder funds. A separate Cayman Islands parallel fund (Brackenholt Senior Lending Fund (Cayman), Ltd.) invests alongside the Fund for non-U.S. investors but is not offered by this Memorandum.",
    "citation": "Section 2.1",
    "quote": "The Fund is structured as an open-end, evergreen vehicle: it has no fixed term, it does not call capital from Limited Partners in drawdowns, and it admits Limited Partners and accepts additional subscriptions monthly at net asset value. It is not redeemable on demand. No Limited Partner may require the Fund to repurchase its Interests, and liquidity is provided only through the quarterly repurchase program described in Section 6. It is not a feeder fund, does not invest through a master fund and has no feeder funds of its own."
  },
  "management_fee": {
    "value": "Standard rate: 1.25% per annum of the Fund's net asset value (net assets, not gross assets and not assets acquired with borrowings or undrawn Credit Facility capacity), accrued monthly at one-twelfth of that rate as of each Valuation Date and payable monthly in arrears; prorated for partial months. Interests held by the Adviser and its personnel bear no Management Fee. As amended for the Investor by the executed side letter (Appendix B): 0.95% per annum of the net asset value of the Investor's Capital Account beginning June 1, 2026, in lieu of 1.25%, reverting to 1.25% beginning the first day of the following calendar month if the Investor's Capital Account falls below $40,000,000 as of the last Valuation Date of any calendar quarter as a result of repurchases (a decline attributable solely to investment performance does not trigger reversion).",
    "citation": "Section 4.1; Appendix B, Paragraph 1",
    "quote": "Beginning June 1, 2026, the Management Fee charged to the Investor's Capital Account shall be calculated at an annual rate of 0.95% of the net asset value of that Capital Account, in lieu of the annual rate of 1.25% described in the Memorandum."
  },
  "performance_fee": {
    "value": "Incentive Fee in two independently calculated parts (single class of Interests): (1) Income Incentive Fee — 12.5% of Pre-Incentive Fee Net Investment Income in excess of the Hurdle Rate, subject to a full catch-up, paid quarterly in arrears; (2) Capital Gains Incentive Fee — 12.5% of cumulative realized capital gains from the Initial Closing Date, net of cumulative realized losses and cumulative unrealized depreciation, less fees previously paid, determined and payable annually in arrears as of December 31 and upon termination of the Advisory Agreement. No clawback of previously paid Capital Gains Incentive Fees. Interests held by the Adviser and its personnel bear no Incentive Fee; no side letter in effect reduces or waives the Incentive Fee (the Appendix B side letter expressly leaves it unmodified).",
    "citation": "Section 4.2 (see also Sections 4.3 and 4.4)",
    "quote": "The Fund pays the Adviser an incentive fee (the \"Incentive Fee\") in two parts, calculated independently of each other: an Income Incentive Fee equal to 12.5% of Pre-Incentive Fee Net Investment Income in excess of the Hurdle Rate, subject to the catch-up, as described in Section 4.3; and a Capital Gains Incentive Fee equal to 12.5% of cumulative net realized capital gains, as described in Section 4.4."
  },
  "hurdle_rate": {
    "value": "Income Incentive Fee only: 1.25% per quarter (5.0% annualized) Hurdle Rate measured on Pre-Incentive Fee Net Investment Income as a rate of return on prior quarter-end net asset value. Soft hurdle with a 100% full catch-up: 100% of income between 1.25% and 1.4286% per quarter (5.7143% annualized) goes to the Adviser, then 12.5% of income above 1.4286%, so that once income reaches 1.4286% the Adviser has received 12.5% of all of it. The Hurdle Rate is not cumulative, does not compound, and quarterly shortfalls are not carried forward. The Capital Gains Incentive Fee has no hurdle or catch-up.",
    "citation": "Section 4.3 (see also Section 4.4)",
    "quote": "Pre-Incentive Fee Net Investment Income for each quarter, expressed as a rate of return on the Fund's net asset value at the end of the immediately preceding quarter, is compared to a hurdle rate of 1.25% per quarter (5.0% annualized) (the \"Hurdle Rate\")."
  },
  "high_water_mark": {
    "value": "No high water mark. For the Income Incentive Fee there is no high-water mark, look-back or loss carryforward, and it may be payable in a quarter in which net asset value declined due to capital losses. For the Capital Gains Incentive Fee, a perpetual Loss Carryforward applies: because the calculation is cumulative from the Initial Closing Date, realized losses and unrealized depreciation carry forward and must be recovered by later net realized gains; the Loss Carryforward is not reset at year end or upon admission or repurchase of Limited Partners.",
    "citation": "Section 4.3; Section 4.4",
    "quote": "There is no high-water mark, look-back or loss carryforward with respect to the Income Incentive Fee, and it may be payable for a quarter in which net asset value declined because of capital losses."
  },
  "minimum_initial_investment": {
    "value": "$1,000,000 minimum initial subscription (minimum additional subscription $100,000), subject to the General Partner's discretion to accept lesser amounts.",
    "citation": "Section 5.2",
    "quote": "The minimum initial subscription is $1,000,000, and the minimum additional subscription is $100,000, in each case subject to the discretion of the General Partner to accept lesser amounts."
  },
  "lockup_period": {
    "value": "No hard lock-up. Soft lock only: a 2.0% Early Repurchase Deduction on the net asset value of Interests repurchased as of a Repurchase Date falling within one year after the Subscription Date on which they were issued, applied first-in, first-out and retained by the Fund. It does not apply to reinvested distributions and may be waived by the General Partner upon death or disability of a natural person Limited Partner or by side letter. Per the executed side letter (Appendix B), the Early Repurchase Deduction does not apply to any Interests held by the Investor (The Trustees of Hallowby College), including additional subscriptions.",
    "citation": "Section 6.4; Appendix B, Paragraph 2",
    "quote": "There is no hard lock-up. Interests repurchased as of a Repurchase Date that falls within one year after the Subscription Date on which they were issued are subject to a deduction of 2.0% of the net asset value of the Interests repurchased (the \"Early Repurchase Deduction\"), applied on a first-in, first-out basis."
  },
  "redemption_frequency": {
    "value": "No redemption or withdrawal right. Discretionary quarterly repurchase offers, as of the last Business Day of each calendar quarter (Repurchase Date); the General Partner intends but is not obligated to make an offer and may decline for any quarter. Repurchase Offer Notice is sent not less than 20 Business Days before the Notice Deadline; offers may be suspended or postponed in specified circumstances.",
    "citation": "Section 6.1 (see also Section 6.5)",
    "quote": "Limited Partners have no right to redeem or withdraw from the Fund. The General Partner currently intends, but is not obligated, to cause the Fund to offer to repurchase Interests quarterly, as of the last Business Day of each calendar quarter (each, a \"Repurchase Date\")."
  },
  "redemption_notice_days": {
    "value": "60 days: an irrevocable written Repurchase Request must be received by the Administrator not later than 60 days prior to the applicable Repurchase Date (the Notice Deadline); late requests must be resubmitted for a later Repurchase Date. A partial request may not reduce a Limited Partner's Capital Account below $500,000. Exception under the executed side letter (Appendix B): following a Key Person Notice, the Investor's request is timely if received not later than 30 days prior to the first Repurchase Date falling at least 30 days after delivery of the notice.",
    "citation": "Section 6.2; Appendix B, Paragraph 3",
    "quote": "A Limited Partner wishing to tender all or part of its Interests must deliver an irrevocable written repurchase request to the Administrator (a \"Repurchase Request\") so that it is received not later than 60 days prior to the applicable Repurchase Date (the \"Notice Deadline\")."
  },
  "gate_provision": {
    "value": "Fund-level gate (not investor-level): 5.0% of the Fund's net asset value as of the last Valuation Date of the immediately preceding calendar quarter per Repurchase Date (the Quarterly Repurchase Limit). Excess timely requests are prorated to amounts requested and unfilled portions do not carry over to the next quarter. The General Partner may, in its sole discretion but with no obligation, repurchase up to an additional 2.0% of net asset value as of any Repurchase Date. Parallel Fund repurchases do not count against the limit.",
    "citation": "Section 6.3",
    "quote": "The aggregate amount of Interests that the Fund will repurchase as of any Repurchase Date is limited to 5.0% of the Fund's net asset value as of the last Valuation Date of the immediately preceding calendar quarter (the \"Quarterly Repurchase Limit\"). The Quarterly Repurchase Limit is applied at the level of the Fund, across all Limited Partners, and not Limited Partner by Limited Partner."
  },
  "key_man_provision": {
    "value": "NOT_APPLICABLE",
    "citation": "Section 3.2; Section 9.4; Appendix B, Paragraph 3",
    "quote": "The Partnership Agreement does not contain a key person provision."
  },
  "gp_commitment": {
    "value": "NOT_APPLICABLE",
    "citation": "Section 3.3",
    "quote": "Neither the General Partner nor the Adviser has made, or is required to make or maintain, any capital commitment to the Fund."
  },
  "fund_term": {
    "value": "Perpetual — no fixed term; the Fund continues until dissolved upon (a) determination of the General Partner on not less than 90 days' prior written notice, (b) withdrawal or bankruptcy of the General Partner unless a majority in interest of Limited Partners elects a successor within 90 days, or (c) a decree of judicial dissolution. The Credit Facility maturity and the Advisory Agreement term do not limit the Fund's term.",
    "citation": "Section 12.2",
    "quote": "The Fund has no fixed term and will continue until dissolved."
  },
  "auditor": {
    "value": "Tessier Mulvane LLP (Denver, Colorado). Kellaway Brisco LLP prepares tax returns and Schedules K-1 but does not audit the Fund.",
    "citation": "Section 8.2; Appendix A",
    "quote": "Tessier Mulvane LLP serves as the independent auditor of the Fund."
  },
  "administrator": {
    "value": "Rendlesham Fund Services, LLC (Boston, Massachusetts)",
    "citation": "Section 8.1; Appendix A",
    "quote": "Rendlesham Fund Services, LLC serves as administrator of the Fund (the \"Administrator\")."
  },
  "prime_broker": {
    "value": "NOT_APPLICABLE",
    "citation": "Section 8.5",
    "quote": "The Fund does not engage a prime broker."
  },
  "legal_counsel": {
    "value": "Pellow Ainsworth LLP (New York, New York) — counsel to the Fund, the General Partner and the Adviser; does not represent the Limited Partners. Rushmere Quaye (George Town, Grand Cayman) acts as Cayman Islands counsel to the Parallel Fund only, not to the Fund.",
    "citation": "Section 8.4; Appendix A",
    "quote": "Pellow Ainsworth LLP acts as legal counsel to the Fund, the General Partner and the Adviser and does not represent the Limited Partners."
  },
  "mfn_election": {
    "value": "Yes. A Limited Partner whose aggregate subscriptions net of repurchases equal or exceed $25,000,000 (an MFN Investor) may elect the benefit of any side letter term granted after the Initial Closing Date to another Limited Partner whose net subscriptions are equal to or less than its own. The General Partner delivers a compendium of electable terms within 60 days after each calendar year end; election must be made within 45 days after delivery. Excluded: terms relating to a Limited Partner's particular legal, regulatory, tax or policy status; confidentiality and public disclosure terms; consents to transfers to affiliates; and rights to be notified of personnel events at the Adviser. A term granted subject to a condition may be elected only subject to the same condition.",
    "citation": "Section 7.2 (see also Appendix B, Paragraph 6)",
    "quote": "Each Limited Partner whose aggregate subscriptions to the Fund, net of amounts repurchased, equal or exceed $25,000,000 (an \"MFN Investor\") may elect the benefit of any side letter term granted after the Initial Closing Date to another Limited Partner whose net subscriptions are equal to or less than its own."
  }
}

